def verify_isbn(isbn: str) -> str:
    """
    Verify the correctness of a given ISBN number and correct it if necessary.

    :param isbn: A string representing the ISBN number to be verified.
    :return: A string that is either "Right" if the ISBN checksum is correct, or the corrected ISBN number
    in the same format as the input if the checksum is incorrect.
    """
    # Check if the input is a valid ISBN number
    if not isbn.isdigit() or len(isbn) != 10:
        raise ValueError("Invalid ISBN number")

    # Calculate the checksum digit
    checksum = 0
    for i in range(9):
        checksum += int(isbn[i]) * (i + 1)
    checksum %= 11
    if checksum == 10:
        checksum = "X"
    elif checksum == 11:
        checksum = 0

    # Compare the checksum digit with the input checksum digit
    if checksum == isbn[9]:
        return "Right"
    else:
        return isbn[:9] + str(checksum)

